// TypeScript Version: 4.1

/**
* Interface describing `snthIndexOf`.
*/
interface Routine {
	/**
	* Returns the index of the n-th occurrence of a specified search element in a single-precision floating-point strided array.
	*
	* ## Notes
	*
	* -   If the function is unable to find the n-th occurrence of a search element, the function returns `-1`.
	*
	* @param N - number of indexed elements
	* @param k - occurrence number. Must be a positive integer specifying which occurrence of the search element to find; `k=1` finds the first occurrence, `k=2` finds the second occurrence, and so on
	* @param searchElement - search element
	* @param x - input array
	* @param strideX - stride length
	* @returns index
	*
	* @example
	* var Float32Array = require( '@stdlib/array/float32' );
	*
	* var x = new Float32Array( [ 1.0, 2.0, 3.0, 2.0 ] );
	*
	* var idx = snthIndexOf( x.length, 2, 2.0, x, 1 );
	* // returns 3
	*/
	( N: number, k: number, searchElement: number, x: Float32Array, strideX: number ): number;

	/**
	* Returns the index of the n-th occurrence of a specified search element in a single-precision floating-point strided array using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   If the function is unable to find the n-th occurrence of a search element, the function returns `-1`.
	*
	* @param N - number of indexed elements
	* @param k - occurrence number. Must be a positive integer specifying which occurrence of the search element to find; `k=1` finds the first occurrence, `k=2` finds the second occurrence, and so on
	* @param searchElement - search element
	* @param x - input array
	* @param strideX - stride length
	* @param offsetX - starting index
	* @returns index
	*
	* @example
	* var Float32Array = require( '@stdlib/array/float32' );
	*
	* var x = new Float32Array( [ 1.0, 2.0, 3.0, 2.0 ] );
	*
	* var idx = snthIndexOf.ndarray( x.length, 2, 2.0, x, 1, 0 );
	* // returns 3
	*/
	ndarray( N: number, k: number, searchElement: number, x: Float32Array, strideX: number, offsetX: number ): number;
}

/**
* Returns the index of the n-th occurrence of a specified search element in a single-precision floating-point strided array.
*
* ## Notes
*
* -   If the function is unable to find the n-th occurrence of a search element, the function returns `-1`.
*
* @param N - number of indexed elements
* @param k - occurrence number
* @param searchElement - search element
* @param x - input array
* @param strideX - stride length
* @returns index
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Array( [ 1.0, 2.0, 3.0, 2.0 ] );
*
* var idx = snthIndexOf( x.length, 2, 2.0, x, 1 );
* // returns 3
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Array( [ 1.0, 2.0, 3.0, 2.0 ] );
*
* var idx = snthIndexOf.ndarray( x.length, 2, 2.0, x, 1, 0 );
* // returns 3
*/
declare var snthIndexOf: Routine;


// EXPORTS //

export = snthIndexOf;
